/**
 * Auditory tone bank + analytic cell↔tone mapping.
 *
 * The bank is **24 sine tones logarithmically spaced from 200 Hz to 3900 Hz**
 * (design §3.2 revised 2026-05-05). Frequencies are
 *   f_k = lowFreqHz × (highFreqHz / lowFreqHz)^((k−1) / (count−1))
 * which puts neighbouring tones at a ratio of (3900/200)^(1/23) ≈ 1.139
 * (~13.9 % per step) — a non-Western interval that adapts Li, Cowan &
 * Saults (2013, *APP* 75(1), p. 150) to a 24-tone variant. The earlier
 * chromatic ladder (220 × 2^((k−1)/12)) was retired because every tone
 * landed on a named pitch class, exposing the bank to note-name re-encoding
 * by musically trained participants. The full rationale (Shepard 1982
 * octave-equivalence avoidance, Sek & Moore 1995 DLF range) sits in
 * `src/config.js` and the design doc; see `src/audio/dsp.js#buildToneBank`.
 *
 * The cell↔tone mapping (§3.3) is *purely analytic* — a tone is **never**
 * shown on the grid and the grid never lights up when a tone plays. The map
 * exists so every tone inherits the on-/off-pattern label of its paired cell,
 * which lets the analyst tabulate the four canonical probe types (T_on, T_off,
 * F_on, F_off) in the same way across auditory and visual memory trials.
 *
 * Mapping rule (unchanged across the §3.2 revision — the rule is rank-based,
 * not frequency-value-based, so reseating the ladder onto a non-musical
 * scale leaves the cell↔tone bijection byte-identical):
 *   - Tones are ranked 1..24 by frequency (rank 1 = lowest = bank index 0).
 *   - Odd-ranked tones (rank 1, 3, ..., 23 — bank indices 0, 2, ..., 22)
 *     pair with the 12 on-pattern cells, in cell-index order.
 *   - Even-ranked tones (rank 2, 4, ..., 24 — bank indices 1, 3, ..., 23)
 *     pair with the 12 off-pattern cells, in cell-index order.
 *
 * The interleaving prevents a "high tones are on-pattern, low are off"
 * shortcut and equates within-trial pitch dispersion across labels.
 *
 * Anchors: design §3.2, §3.3, §6.2 (probe types).
 */
import { config } from '../config.js';
import { onPatternCells, offPatternCells } from '../grid.js';
import {
  buildToneBank,
  playSineTone,
  isAudioMuted,
  getUserPlaybackGain,
  _registerScheduledAudioNode,
  _unregisterScheduledAudioNode,
} from './dsp.js';
import { getAudioContext } from './context.js';
import { equalLoudnessGainDb70Phon } from './equal-loudness.js';

let TONE_BANK = null;
let CELL_TO_TONE = null;
let TONE_TO_CELL = null;

function buildOnce() {
  if (TONE_BANK !== null) return;

  const { count, low_freq_hz, high_freq_hz } = config.tones;
  const raw = buildToneBank(count, low_freq_hz, high_freq_hz);
  const bank = raw.map((t) => ({
    index: t.index,
    rank: t.index + 1,
    freq_hz: t.freq_hz,
    /* ISO 226:2003 70-phon equal-loudness compensation, computed by
     * interpolation between the tabulated 60-phon and 80-phon contours
     * (per supervisor request, Cowan 2026-05-06). The dB value is the
     * gain needed at this tone's frequency to elicit the same loudness
     * as a 1 kHz reference at 70 phons. Applied at synthesis time by
     * `playToneByIndex`. Range across 200..3900 Hz is roughly +6 dB at
     * the low end to −5 dB near the ear's 2.5–3 kHz sensitivity peak. */
    gain_compensation_db: equalLoudnessGainDb70Phon(t.freq_hz),
    pattern_label: t.index % 2 === 0 ? 'on' : 'off' /* odd rank ⇔ even index ⇔ 'on' */,
    paired_cell: null /* filled below */,
  }));

  const onCells = onPatternCells();
  const offCells = offPatternCells();
  if (onCells.length * 2 !== count || offCells.length * 2 !== count) {
    throw new Error(
      `Tone bank build: expected 12 on-pattern + 12 off-pattern cells for 24 tones; got ${onCells.length} + ${offCells.length}`
    );
  }

  /* Walk the bank: even-index tones (0, 2, 4, ...) take on-pattern cells in
   * order; odd-index tones take off-pattern cells in order. */
  let onCursor = 0;
  let offCursor = 0;
  for (const tone of bank) {
    if (tone.pattern_label === 'on') {
      tone.paired_cell = onCells[onCursor++];
    } else {
      tone.paired_cell = offCells[offCursor++];
    }
  }

  if (onCursor !== onCells.length || offCursor !== offCells.length) {
    throw new Error(
      `Tone bank build: cursor mismatch (on ${onCursor}/${onCells.length}, off ${offCursor}/${offCells.length})`
    );
  }

  TONE_BANK = Object.freeze(bank.map((t) => Object.freeze(t)));

  const cellMap = new Map();
  const toneMap = new Map();
  for (const t of TONE_BANK) {
    cellMap.set(t.paired_cell, t);
    toneMap.set(t.index, t.paired_cell);
  }
  CELL_TO_TONE = cellMap;
  TONE_TO_CELL = toneMap;
}

export function getToneBank() {
  buildOnce();
  return TONE_BANK;
}

export function toneByIndex(toneIndex) {
  buildOnce();
  const t = TONE_BANK[toneIndex];
  if (!t) throw new Error(`toneByIndex: ${toneIndex} out of range 0..${TONE_BANK.length - 1}`);
  return t;
}

export function toneForCell(cellIndex) {
  buildOnce();
  const t = CELL_TO_TONE.get(cellIndex);
  if (!t)
    throw new Error(`toneForCell: cell ${cellIndex} has no paired tone (centre or out of range)`);
  return t;
}

export function cellForToneIndex(toneIndex) {
  buildOnce();
  const c = TONE_TO_CELL.get(toneIndex);
  if (c === undefined) throw new Error(`cellForToneIndex: ${toneIndex} unmapped`);
  return c;
}

export function tonesByLabel(label) {
  buildOnce();
  if (label !== 'on' && label !== 'off') {
    throw new Error(`tonesByLabel: label must be 'on' or 'off', got '${label}'`);
  }
  return TONE_BANK.filter((t) => t.pattern_label === label);
}

/**
 * Play a tone identified by its bank index (or by cell, via toneForCell).
 * Returns a Promise that resolves when the tone has finished.
 */
export function playToneByIndex(toneIndex, opts = {}) {
  const t = toneByIndex(toneIndex);
  return playSineTone(t.freq_hz, {
    durationMs: opts.durationMs ?? config.tones.duration_ms,
    rampMs: opts.rampMs ?? config.tones.cosine_ramp_ms,
    peak: opts.peak,
    /* Per-tone equal-loudness compensation. Caller can override (the
     * tone-familiarisation step does not, but a future "uncompensated
     * audit" tool could). */
    gainDb: opts.gainDb ?? t.gain_compensation_db,
    when: opts.when,
  });
}

export function playToneByCell(cellIndex, opts = {}) {
  return playToneByIndex(toneForCell(cellIndex).index, opts);
}

/**
 * Pink-noise burst (auditory dummy, used in I-only trials per §3.4).
 *
 * Implementation: white noise synthesised into an AudioBuffer, smoothed by
 * Paul Kellet's "economical" 1/f filter. 350 ms by default, cosine envelope.
 * Spectrum doesn't have to be lab-grade pink — it's a placeholder participants
 * are told to ignore — we just want it audibly different from a sine.
 */
export function playPinkNoise(opts = {}) {
  if (isAudioMuted()) return Promise.resolve();
  const ctx = getAudioContext();
  const durationMs = opts.durationMs ?? config.tones.duration_ms;
  const rampMs = opts.rampMs ?? config.tones.cosine_ramp_ms;
  /* Apply the user-set playback gain captured by the audibility/comfort
   * step, mirroring `playSineTone`/`playStereoSine` so the auditory dummy
   * scales with the participant's chosen comfort level. */
  const peak = (opts.peak ?? 0.18) * getUserPlaybackGain();
  const when = opts.when ?? ctx.currentTime;

  const sampleRate = ctx.sampleRate;
  const length = Math.ceil((durationMs / 1000) * sampleRate);
  const buf = ctx.createBuffer(1, length, sampleRate);
  const data = buf.getChannelData(0);

  /* Paul Kellet 7-pole filter; very small bias, well-known approximation. */
  let b0 = 0,
    b1 = 0,
    b2 = 0,
    b3 = 0,
    b4 = 0,
    b5 = 0,
    b6 = 0;
  for (let i = 0; i < length; i++) {
    const white = Math.random() * 2 - 1;
    b0 = 0.99886 * b0 + white * 0.0555179;
    b1 = 0.99332 * b1 + white * 0.0750759;
    b2 = 0.969 * b2 + white * 0.153852;
    b3 = 0.8665 * b3 + white * 0.3104856;
    b4 = 0.55 * b4 + white * 0.5329522;
    b5 = -0.7616 * b5 - white * 0.016898;
    const pink = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
    b6 = white * 0.115926;
    data[i] = pink * 0.11; /* normalise so peak ≲ 1 */
  }

  const src = ctx.createBufferSource();
  src.buffer = buf;
  const gain = ctx.createGain();
  const rampSec = rampMs / 1000;
  const durSec = durationMs / 1000;
  gain.gain.setValueAtTime(0, when);
  gain.gain.linearRampToValueAtTime(peak, when + rampSec);
  gain.gain.setValueAtTime(peak, when + durSec - rampSec);
  gain.gain.linearRampToValueAtTime(0, when + durSec);

  src.connect(gain).connect(ctx.destination);
  src.start(when);
  src.stop(when + durSec + 0.05);
  const entry = _registerScheduledAudioNode({ sources: [src], gains: [gain] });
  return new Promise((resolve) => {
    src.onended = () => {
      _unregisterScheduledAudioNode(entry);
      resolve();
    };
  });
}
